namespace ReactiveUI.Documentation.DataPersistence;

/// <summary>
/// Shows <c>AutoPersist</c> using the compile-time <c>AutoPersistMetadata</c> generated by <c>[AutoPersist]</c> so no
/// manual property list or runtime reflection is needed.
/// </summary>
public static class GeneratedAutoPersistExamples
{
    /// <summary>
    /// Passes <c>GeneratedNote.AutoPersistMetadata</c> directly to <c>AutoPersist</c>, watching only
    /// <c>[DataMember]</c> properties under trimming and Native AOT.
    /// </summary>
    /// <returns>A task that completes once the debounced save has run.</returns>
    public static async Task SavesUsingGeneratedMetadata()
    {
        GeneratedNote note = new() { Title = "Packing list" };

        Console.WriteLine(GeneratedNote.AutoPersistMetadata.HasDataContract);
        Console.WriteLine(GeneratedNote.AutoPersistMetadata.PersistablePropertyNames.Count);

        int saveCount = 0;
        using IDisposable subscription = note.AutoPersist(
            _ =>
            {
                saveCount++;
                return Signal.Emit(RxVoid.Default);
            },
            GeneratedNote.AutoPersistMetadata,
            TimeSpan.FromMilliseconds(30));

        note.Body = "Passport, charger";
        await Task.Delay(TimeSpan.FromMilliseconds(100));

        Console.WriteLine(saveCount);

        // Output:
        // True
        // 2
        // 1
    }
}
